function validate([picture]) {
  if (!Array.isArray(picture) || picture.length < 1 || picture.length > 500) return 'picture needs 1 to 500 rows.';
  const cols = picture[0].length;
  if (cols < 1 || cols > 500) return 'picture needs 1 to 500 columns.';
  if (picture.some(row => !Array.isArray(row) || row.length !== cols)) return 'Every row of picture must have the same length.';
  if (picture.some(row => row.some(ch => ch !== 'B' && ch !== 'W'))) return "Each cell is 'B' or 'W'.";
  return null;
}

