function findLonelyPixel(picture) {
  // For every black pixel, scan its whole row and column for another black one.
  let total = 0;
  picture.forEach((line, r) => line.forEach((cell, c) => {
    if (cell !== 'B') return;
    const inRow = line.filter(x => x === 'B').length;
    const inCol = picture.map(other => other[c]).filter(x => x === 'B').length;
    if (inRow === 1 && inCol === 1) total += 1;
  }));
  return total;
}

