function generate(rand, size) {
  const rows = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  const cols = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  // Sparse pictures have many lonely pixels; denser ones have few or none.
  const density = size === 'large' ? [0.002, 0.008, 0.02, 0.1][Math.floor(rand() * 4)] : rand() * 0.6;
  return [Array.from({ length: rows }, () => Array.from({ length: cols }, () => (rand() < density ? 'B' : 'W')))];
}
